class Cache:
    def __init__(self):
        self._store = {}

    def put(self, key, value, now, ttl):
        if ttl <= 0:
            if key in self._store:
                del self._store[key]
            return
        self._store[key] = (value, now + ttl)

    def get(self, key, now):
        if key not in self._store:
            return None
        value, expiry = self._store[key]
        if now >= expiry:
            del self._store[key]
            return None
        return value
