def merge_patch(target, patch):
    """
    Implement merge_patch per RFC7396.

    - If patch is not a dict, it replaces target entirely.
    - If patch is a dict, it recursively merges into a copy of target (or an empty dict if target is not a dict).
    - Null values in the patch delete the corresponding key from the result.
    - Neither input is mutated.
    """
    # If patch is not a dict, it replaces target entirely
    if not isinstance(patch, dict):
        return patch

    # If target is not a dict, start with an empty dict
    if not isinstance(target, dict):
        result = {}
    else:
        # Make a copy of target to avoid mutating it
        result = target.copy()

    # Recursively merge the patch into the result
    for key, value in patch.items():
        if value is None:
            # Null values delete the key
            if key in result:
                del result[key]
        elif isinstance(value, dict):
            # Recursively merge if the patch value is a dict
            if key in result and isinstance(result[key], dict):
                result[key] = merge_patch(result[key], value)
            else:
                # If the target doesn't have this key or it's not a dict, use the patch value
                result[key] = merge_patch({}, value)
        else:
            # For non-dict, non-null values, just assign
            result[key] = value

    return result
