def retry(fn, attempts, retryable):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    last_exception = None
    for _ in range(attempts):
        try:
            return fn()
        except retryable as e:
            last_exception = e
        except Exception:
            raise

    raise last_exception
